    if(forced.size()!=32) return 4;
    auto weights=gguf::read_gguf(argv[1]);
    infer::Model model(weights);
    model.set_threads(6);model.set_ubatch(128);
    bpe::Tokenizer tok(weights);
    std::ifstream input(argv[2],std::ios::binary);
    std::string text((std::istreambuf_iterator<char>(input)),{});
    auto ids=tok.encode(text);
    if(ids.size()!=1943) return 3;
#ifdef ACTIVE_WITNESS
    witness::caller = GetCurrentThreadId();
    witness::prefill = true;
#endif
    auto logits=model.prefill(ids);
#ifdef ACTIVE_WITNESS
    witness::prefill = false;
    if (witness::applies != 6 || witness::restores != 6 || witness::caller_applies != 1)
        throw std::runtime_error("six-participant prefill inactive");
#endif
    auto save=[&](const std::string& suffix) {
        std::ofstream output(std::string(argv[3])+suffix,std::ios::binary);
        output.write((const char*)logits.data(),logits.size()*sizeof(float));
        if(!output) throw std::runtime_error("write failed");
    };
    save("-logits.f32");
    for(int i=0;i<32;++i) {
        int token=(int)(std::max_element(logits.begin(),logits.end())-logits.begin());
        std::cout << token << " ";
        logits=model.step(forced[size_t(i)]);
        save("-step-"+std::string(i<10?"0":"")+std::to_string(i)+".f32");
    }
    std::cout << "\n";
#ifdef ACTIVE_WITNESS
    std::ostringstream report;
    auto* saved = std::cout.rdbuf(report.rdbuf());
    try { witness::print(); }
    catch (...) { std::cout.rdbuf(saved); throw; }
    std::cout.rdbuf(saved);
    std::cerr << "PLACEMENT_WITNESS " << report.str() << '\n';
#endif
}

