using Clock=std::chrono::steady_clock;
static double counter_seconds() {
    static const double frequency = [] {
        LARGE_INTEGER value;
        if (!QueryPerformanceFrequency(&value)) throw std::runtime_error("QPC frequency unavailable");
        return double(value.QuadPart);
    }();
    LARGE_INTEGER value;
    if (!QueryPerformanceCounter(&value)) throw std::runtime_error("QPC unavailable");
    return double(value.QuadPart) / frequency;
}
int main(int argc,char** argv) {
    try {
        if(argc!=6)throw std::runtime_error("usage: placement-model MODEL TOKENS OUTPUT production|scheduler|prefill primary|followup1|followup9");
#if defined(LLMX_PLACEMENT_WITNESS)
        witness::caller = GetCurrentThreadId();
#endif
        const std::string_view mode(argv[4]);
        if(mode!="production"&&mode!="scheduler"&&mode!="prefill")throw std::runtime_error("invalid placement mode");
        auto weights=gguf::read_gguf(argv[1]);auto cpu=std::make_shared<backend::CpuBackend>();
        infer::Model model(weights,cpu);model.set_threads(6);model.set_ubatch(128);
#if !defined(LLMX_CALLBACK_PRODUCTION)
        cpu->set_prefill_placement(mode=="prefill");
        if(mode=="production")throw std::runtime_error("wrong executable for production mode");
#else
        if(mode!="production")throw std::runtime_error("wrong executable for prototype mode");
#endif
        const std::string_view workload(argv[5]);
        const size_t pp_tokens = workload=="primary" ? 215 : workload=="followup1" ? 1 : workload=="followup9" ? 9 : 0;
        if(!pp_tokens)throw std::runtime_error("invalid workload");
        std::ifstream input(argv[2]);std::vector<uint32_t> ids;uint32_t id;while(input>>id)ids.push_back(id);
        if(!input.eof()||ids.size()!=247||cpu->threads_available()!=6)throw std::runtime_error("invalid input or threads");
        std::vector<uint32_t> prefix(ids.begin(),ids.begin()+215-pp_tokens);
        std::vector<uint32_t> prompt(ids.begin()+215-pp_tokens,ids.begin()+215);std::vector<float> warmup,final;
        struct Record {double pp,tg,begin,prefill_end,end;uint64_t hash;};
        Record records[2]{};
        for(int run=0;run<2;++run) {
            model.reset();
#if defined(LLMX_PLACEMENT_WITNESS)
            witness::prefill = true;
#endif
            if(!prefix.empty())model.prefill(prefix);
            records[run].begin=counter_seconds();
            auto start=Clock::now();
            auto logits=model.prefill(prompt);
            auto pp_end=Clock::now();
            records[run].prefill_end=counter_seconds();
#if defined(LLMX_PLACEMENT_WITNESS)
            witness::prefill = false;
#endif
            for(size_t i=215;i<ids.size();++i)logits=model.step(ids[i]);
            auto tg_end=Clock::now();
            records[run].end=counter_seconds();
            records[run].pp=std::chrono::duration<double,std::milli>(pp_end-start).count();
            records[run].tg=std::chrono::duration<double,std::milli>(tg_end-pp_end).count();
            uint64_t hash=14695981039346656037ull;
            for(float value:logits){if(!std::isfinite(value))throw std::runtime_error("nonfinite logit");uint32_t bits;std::memcpy(&bits,&value,4);for(int shift=0;shift<32;shift+=8){hash^=(bits>>shift)&255;hash*=1099511628211ull;}}
            records[run].hash=hash;
            if(!run)warmup=logits;
            else{if(logits.size()!=warmup.size()||std::memcmp(logits.data(),warmup.data(),logits.size()*4))throw std::runtime_error("warmup/final vector differs");final=std::move(logits);}
        }
        std::ofstream output(argv[3],std::ios::binary);output.exceptions(std::ios::badbit|std::ios::failbit);
        output.write(reinterpret_cast<const char*>(final.data()),std::streamsize(final.size()*sizeof(float)));output.close();
        std::cout<<std::setprecision(15)<<"{\"caller_thread_id\":"<<std::hash<std::thread::id>{}(std::this_thread::get_id())<<",\"mode\":\""<<mode<<"\",\"workload\":\""<<workload<<"\",\"threads\":6,\"ubatch\":128,\"pp_tokens\":"<<pp_tokens<<",\"tg_tokens\":32,\"vocab\":"<<final.size()<<",\"records\":[";
        for(int i=0;i<2;++i){if(i)std::cout<<',';const auto& r=records[i];std::cout<<"{\"run\":"<<i<<",\"pp_ms\":"<<r.pp<<",\"tg_ms\":"<<r.tg<<",\"qpc_begin\":"<<r.begin<<",\"qpc_prefill_end\":"<<r.prefill_end<<",\"qpc_end\":"<<r.end<<",\"final_fnv64\":\""<<std::hex<<r.hash<<std::dec<<"\"}";}
        std::cout<<"]";
#if defined(LLMX_PLACEMENT_WITNESS)
        std::cout<<",\"witness\":"; witness::print();
#endif
        std::cout<<"}\n";
    }catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}
}

#include "witness.hpp"
#include <sstream>
#define main llmx_cli_main
#include "cli/main.cpp"
#undef main

int main(int argc, char** argv) {
    if (argc < 2 || std::string(argv[1]) != "logits") {
        std::cerr << "witness CLI accepts logits only\n";
        return 2;
    }
    witness::caller = GetCurrentThreadId();
    witness::prefill = true;
    const int result = llmx_cli_main(argc, argv);
    witness::prefill = false;
    if (result) return result;
    if (witness::applies != 6 || witness::restores != 6 || witness::caller_applies != 1) {
        std::cerr << "expected one active six-participant prefill\n";
        return 3;
    }
    try {
        std::ostringstream report;
        auto* saved = std::cout.rdbuf(report.rdbuf());
        try { witness::print(); }
        catch (...) { std::cout.rdbuf(saved); throw; }
        std::cout.rdbuf(saved);
        std::cerr << "PLACEMENT_WITNESS " << report.str() << '\n';
    } catch (const std::exception& error) {
        std::cerr << error.what() << '\n';
        return 4;
    }
    return 0;
}

