namespace witness {
inline const auto real_set = &SetThreadAffinityMask;
inline std::atomic<bool> prefill{false};
inline std::atomic<unsigned long long> applies{0}, restores{0}, errors{0}, active{0}, outside{0}, caller_applies{0};
inline std::array<std::atomic<unsigned long long>, 64> per_cpu{};
inline DWORD caller = 0;
inline thread_local DWORD_PTR old_mask = 0, target_mask = 0;
inline void check(bool ok) { if (!ok) ++errors; }
inline DWORD_PTR WINAPI set(HANDLE thread, DWORD_PTR mask) {
    if (!prefill.load()) ++outside;
    GROUP_AFFINITY before{};
    check(GetThreadGroupAffinity(thread, &before) != 0 && before.Group == 0);
    const auto previous = real_set(thread, mask);
    if (!previous) { ++errors; return previous; }
    GROUP_AFFINITY after{};
    PROCESSOR_NUMBER actual{};
    check(GetThreadGroupAffinity(thread, &after) != 0 && after.Group == 0 && after.Mask == mask);
    GetCurrentProcessorNumberEx(&actual);
    check(actual.Group == 0 && actual.Number < 64 && (mask & (DWORD_PTR(1) << actual.Number)));
    if (old_mask) {
        check(mask == old_mask && previous == target_mask);
        ++restores; --active; old_mask = target_mask = 0;
    } else {
        check(mask && !(mask & (mask - 1)) && previous == before.Mask && (mask & before.Mask) == mask);
        old_mask = previous; target_mask = mask; ++applies; ++active;
        if (GetCurrentThreadId() == caller) ++caller_applies;
        if (actual.Number < 64) ++per_cpu[actual.Number];
    }
    return previous;
}
inline void print() {
    if (errors.load() || active.load() || outside.load()) throw std::runtime_error("model placement witness failed");
    std::cout << "{\"applies\":" << applies.load() << ",\"restores\":" << restores.load()
        << ",\"errors\":" << errors.load() << ",\"active_after_decode\":" << active.load()
        << ",\"outside_prefill_setters\":" << outside.load() << ",\"caller_applies\":" << caller_applies.load() << ",\"per_cpu_applies\":[";
    for (size_t i = 0; i < per_cpu.size(); ++i) { if (i) std::cout << ','; std::cout << per_cpu[i].load(); }
    std::cout << " ]}";
}
